draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // sun
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W/2, H/4, 50, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // tree
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.arc(W/2, H*3/4, 30, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H*3/4 + 30);
  ctx.lineTo(W/2, H);
  ctx.stroke();

  // character
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 + 100*Math.sin(t), H*3/4 - 50, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100*Math.sin(t), H*3/4 - 30);
  ctx.lineTo(W/2 + 100*Math.sin(t), H*3/4 - 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100*Math.sin(t), H*3/4 - 60);
  ctx.lineTo(W/2 + 100*Math.sin(t) - 30, H*3/4 - 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100*Math.sin(t), H*3/4 - 60);
  ctx.lineTo(W/2 + 100*Math.sin(t) + 30, H*3/4 - 40);
  ctx.stroke();

  // event text
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('1704', W/2 + 100*Math.sin(t), H*3/4 - 100);

  ctx.restore();
}
